// Learn Attribute:
//  - https://docs.cocos.com/creator/manual/en/scripting/reference/attributes.html
// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {

        _soundCfg:null,
        _turn_wheel:0,
    },

    // LIFE-CYCLE CALLBACKS:

    Init () {
        this._wheelData1 = [ "HEPHAESTUS", "MAJOR", "MINI", "MEGA", "MINOR", "MAJOR", "MINI", "MINOR", "MEGA", "MINI"];
        this._wheelData2 = [10, 3, 1, 5, 2, 3, 1, 2, 5, 1];

        this._node_wheel = cc.find('safe_node/node_wheel',this.node);
        this._node_wheel.active = false;

        this._nodeUI = cc.find('node',this._node_wheel);

        this._wheel_1 = cc.find('node/wheel_1',this._node_wheel);
        this._wheel_2 = cc.find('node/wheel_2',this._node_wheel);

        this._spine_spin = cc.find('node/spine_spin',this._node_wheel);
        this._node_result = cc.find('node/wheel_2/node_result',this._node_wheel);

        // this._btn_start = cc.find('node/btn_start',this._node_wheel);
    },

    start () {

    },

    async gainWheel(data){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.playBgm("wheel_bgm");

            this._result = data;
            this._node_wheel.active = true;
            this.recoverAllNode();

            // 奖池在上层
            this.setJackPotGray(false);

            //1.转盘出现
            await this.showWheel();

            //2.准备转盘1
            await this.readyWheel1();

            //3.转盘1转动
            await this.moveWheel(1);

            //4.转盘1结果动画
            await this.showResultAnim(1);

            //5.转盘1结果展示
            await this.showResultWheel1();

            // 奖池在下层
            this.setJackPotGray(true);

            //6.准备转盘2
            await this.readyWheel2();

            //7.转盘2转动
            await this.moveWheel(2);

            //8.转盘2结果动画
            await this.showResultAnim(2);

            //9.转盘2结果展示
            await this.showResultWheel2();

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("bonus_bgm");

            sucess();
            await this.awaitTime(0.5);
            this._node_wheel.active = false;
            // 恢复奖池上层
            this.setJackPotGray(false);
        });
    },

    recoverAllNode(){
        this._nodeUI.active = true;
        this._nodeUI.opacity = 255;

        this._wheel_1.position = cc.find("node/pos_1",this._node_wheel).position;
        this._wheel_2.position = cc.find("node/pos_2",this._node_wheel).position;

        cc.find('spr_di',this._wheel_1).angle = 0;
        cc.find('spr_di',this._wheel_2).angle = 0;
        cc.find('spr_multi',this._wheel_2).y = 0;
        cc.find('spr_multi',this._wheel_2).active = false;
        cc.find('spine_light',this._wheel_2).active = false;

        this._spine_spin.active = false;

        this._node_result.active = false

    },

    // 显示转盘
    showWheel(){
        return new Promise((sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("wheel_popup");
            this._nodeUI.position = cc.find("pos_s",this._node_wheel).position;
            cc.tween(this._nodeUI)
                .to(1,{position:cc.v2(0,0)},{easing:"backOut"})
                .call(()=>{
                    sucess();
                })
                .start()
        });
    },

    // 准备转盘1
    readyWheel1(){
        return new Promise(async(sucess, failed)=> {
            this._spine_spin.active = true;
            this._spine_spin.getComponent(sp.Skeleton).setAnimation(0,"animation1_1",false);
            this._spine_spin.getComponent(sp.Skeleton).addAnimation(0,"animation1_2",true);

            await this.awaitTime(1);
            let btn = cc.find('node/btn_start_1',this._node_wheel);
            btn.active = true;
            btn.getComponent(cc.Button).interactable = true;
            btn.off("click");
            let self = this;
            let clickFunc = async()=> {
                Global.SlotsSoundMgr.playEffect("click");
                btn.getComponent(cc.Button).interactable = false;
                btn.active = false;

                self._spine_spin.getComponent(sp.Skeleton).setAnimation(0,"animation1_3",false);
                await this.awaitTime(0.5);

                self._spine_spin.active = false;
                sucess();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=> {
                btn.stopAllActions();
                clickFunc();
            })
        });
    },

    // 轮盘转动
    moveWheel:function(type){
        return new Promise(async(sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("wheel_spin");

            let objLun;     //转盘
            let nCir = 4;   //圈数
            let nTotal;     //转盘总转动角度

            let normalIdx = this._result.rs_1.idx;      //this._result.rs_1.idx、this._result.rs_2.idx 从1开始
            let normalLength = 10;
            let bonusIdx = this._result.rs_2.idx;
            let bonusLength = 10;
            this._result_wheel2 = this._result.rs_2.coin;   // 转盘1的赢得的值

            if(type === 1){ //普通转盘
                objLun = cc.find('spr_di',this._wheel_1);
                nTotal = (normalLength-(normalIdx-1))*(360/normalLength) + nCir*360;
            } else {
                objLun = cc.find('spr_di',this._wheel_2);
                nTotal = (bonusLength-(bonusIdx-1))*(360/bonusLength) + nCir*360;
            }

            let self = this;
            cc.tween(objLun)
                .by(7,{angle:-nTotal},{easing:'quadInOut'})
                .call(()=>{
                    sucess();
                })
                .start();
        });
    },

    // 显示转盘结果动画
    showResultAnim(type){
        return new Promise(async(sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("word");
            if (type === 1) {
                //转盘1中奖item
                let spine_result = cc.find('spine_result', this._wheel_1);
                spine_result.active = true;
                spine_result.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                spine_result.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    spine_result.active = false;
                    sucess()
                });
            } else if (type === 2) {
                //转盘2中奖item
                let spine_result = cc.find('spine_result', this._wheel_2);
                spine_result.active = true;
                spine_result.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                spine_result.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    spine_result.active = false;
                    sucess()
                });
            }
        })
    },

    // 转盘1结果
    showResultWheel1(){
        return new Promise(async(sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("wheel_stop1");

            let spr_title = cc.find('spr_title',this._node_result);
            let lbl_result = cc.find('lbl_result',this._node_result);

            let result_id = this.getJpType(this._result.rs_1.idx-1);  // 标题类别
            spr_title.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("base_game").getSpriteFrame('theme_jackpot_'+result_id);
            lbl_result.getComponent(cc.Label).string = "";

            this._node_result.active = true;
            this._node_result.setScale(0);
            cc.tween(this._node_result).to(1,{scale:1},{easing:"backOut"}).start();
            await this.awaitTime(1);


            Global.SlotsSoundMgr.playEffect("qianshu");
            Global.doRoallNumEff(lbl_result,0,this._result.rs_1.coin,0.7,null,null,0,true);
            await this.awaitTime(0.7);
            Global.SlotsSoundMgr.stopEffectByName("qianshu");

            sucess();
        })
    },

    // 准备转盘2
    readyWheel2(){
        return new Promise(async(sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("wheel_popup");

            let endPos = cc.find("node/pos_1",this._node_wheel).position;
            cc.tween(this._wheel_2).to(1,{position:endPos}).start();

            await this.awaitTime(1);
            this._spine_spin.active = true;
            this._spine_spin.getComponent(sp.Skeleton).setAnimation(0,"animation2_1",false);
            this._spine_spin.getComponent(sp.Skeleton).addAnimation(0,"animation2_2",true);

            await this.awaitTime(1);
            let btn = cc.find('node/btn_start_2',this._node_wheel);
            btn.active = true;
            btn.getComponent(cc.Button).interactable = true;
            btn.off("click");
            let self = this;
            let clickFunc = async()=> {
                Global.SlotsSoundMgr.playEffect("click");
                btn.getComponent(cc.Button).interactable = false;
                btn.active = false;

                self._spine_spin.getComponent(sp.Skeleton).setAnimation(0,"animation2_3",false);
                await this.awaitTime(0.5);

                self._spine_spin.active = false;
                sucess();
            };
            cc.vv.gameData.checkAutoPlay(btn, clickFunc);
            btn.on("click", async()=> {
                btn.stopAllActions();
                clickFunc();
            })
        });
    },

    // 转盘2结果展示
    showResultWheel2(){
        return new Promise(async(sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("wheel_stop2");

            let spine_light = cc.find('spine_light',this._wheel_2);
            spine_light.active = true;
            spine_light.setScale(1);
            spine_light.getComponent(sp.Skeleton).setAnimation(0,'animation',false);
            spine_light.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spine_light.active = false;
            });

            let spr_multi = cc.find('spr_multi',this._wheel_2);
            let lbl_result = cc.find('lbl_result',this._node_result);
            let spine_result = cc.find('spine_result',this._node_result);

            let multi_id = this.getMultType(this._result.rs_2.idx-1);
            spr_multi.active = true;
            spr_multi.setScale(2);
            spr_multi.opacity = 255
            spr_multi.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("mini_game").getSpriteFrame('theme_bonus_multi_'+multi_id);

            await this.awaitTime(0.5);
            Global.SlotsSoundMgr.playEffect("jackpotframe");
            cc.tween(spr_multi)
                .to(1,{position:this._node_result.position, scale:1})
                .to(0.5,{opacity:0})
                .start()
            cc.tween(spine_light).to(0.5,{scale:0}).start()

            await this.awaitTime(1);
            spine_result.active = true;
            spine_result.getComponent(sp.Skeleton).setAnimation(0,'animation',false);
            spine_result.getComponent(sp.Skeleton).setCompleteListener(()=>{spine_result.active = false;});
            Global.doRoallNumEff(lbl_result,this._result.rs_1.coin,this._result.rs_2.coin,1.5,null,null,0,true);

            await this.awaitTime(1.5);
            cc.tween(this._nodeUI)
                .to(0.5,{opacity:0})
                .call(()=>{
                    sucess();
                })
                .start()
        });
    },

    getJpType(idx){
        let str = this._wheelData1[idx];
        let result_id = 1;  // 标题类别
        if(str == "HEPHAESTUS"){
            result_id = 0
        }else if(str == "MEGA"){
            result_id = 1
        }else if(str == "MAJOR"){
            result_id = 2
        }else if(str == "MINOR"){
            result_id = 3
        }else if(str == "MINI"){
            result_id = 4
        }

        return result_id;
    },

    getMultType(idx){
        return this._wheelData2[idx];
    },

    setJackPotGray(bGray){
        let prizePool = cc.find("Canvas/safe_node/LMSlots_PrizePool_1");
        if(bGray){
            cc.tween(prizePool)
                .to(0.5,{opacity:0})
                .start()
        } else {
            cc.tween(prizePool)
                .to(0.5,{opacity:255})
                .start()
        }
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },
    
    // update (dt) {},
});
