// Learn Attribute:
//  - https://docs.cocos.com/creator/manual/en/scripting/reference/attributes.html
// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _isSixTri:false,   // 当前为6个火神触发bonus
        _triFreeIdxs:[],   // 触发免费的牌

        _isInitEntry:true,  // 初始进入游戏
    },

    start () {

    },

    Init(top,bottom){
        this._isInitEntry = true;
        //队列弹窗结束
        Global.registerEvent(EventId.END_QUEUE_POP,this.onEventEndQueuePop,this);

        this._node_banner = cc.find("node_banner", this.node);

        this._node_free_spins = cc.find("node_free_spins", this.node);
        this._node_free_spins.active = false;

        this._top_free = cc.find("top_free", this.node);
        this.hideAllFreeCnt();
        this.setBgMask(false);

        this._super(top,bottom);
    },

    RegisterEvent:function(){
        this._super();

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,this.onEventTotalbetUpdated,this)// 押注额改变
    },

    // 断线重连
    async ReconnectShow(){
        this.initBannerState();

        if (cc.vv.gameData.GetTotalFree() > 0){
            this.ShowGameview(true);
        }else {
            this.ShowGameview(false);
        }

        if(cc.vv.gameData.GetBonusAll()>0){
            cc.vv.gameData.GetBonusScript().enterBonusGame();

        }else{
            this.CanDoNextRound()
        }
    },

    onEventEndQueuePop(){
        // 首次进入游戏，等弹窗关闭后，再播放进入音效和动画
        if(this._isInitEntry){
            this._isInitEntry = false;

            let isFree = cc.vv.gameData.GetTotalFree()>0;
            let isBonus = cc.vv.gameData.GetBonusAll()>0;
            if(isFree || isBonus){
                this.playCharacterAnim(isFree);
            } else {
                this.playEnterGameEff();
            }
        }
    },

    playEnterGameEff(){
        Global.SlotsSoundMgr.playEffect("welcome");
        let node = cc.find("Canvas/safe_node/leishen");
        let entry = node.getComponent(sp.Skeleton).setAnimation(0,"skill",false);
        node.getComponent(sp.Skeleton).setTrackCompleteListener(entry, ()=>{
            node.getComponent(sp.Skeleton).setTrackCompleteListener(entry,null);
            this.playCharacterAnim();
        })
    },

    onMsgSpine(msg){
        if(cc.vv.gameData.IsBonusGame()){
            cc.vv.gameData.GetBonusScript().onMsgSpine(msg)
        } else {
            this._gameInfo = msg
            let cards = msg.resultCards

            // cards = [3,3,3,4,5, 3,3,3,3,3, 111,4,4,4,4, 111,5,5,5,5, 111,5,5,5,5, 111,7,7,7,7]

            cards = this.dealCards(cards);
            this.SetSlotsResult(cards)
            this.SetReelStateInfo(cards)
        }

        // bonus游戏
        if(msg.fireGame && msg.fireGame.tri){

            this.SetStopTime(1000);

            let self = this;
            cc.tween(this.node)
                .delay(this._cfg.auto_stop_time)
                .call(()=>{
                    self._reels[0].StopMove(0)
                })
                .start();
        }


    },


    dealCards(cards){
        for(let col = 0; col < this._col; col++){
            let count = 0;
            let hasScatterList = [0,0,0,0,0,0];
            for (let row = 0; row < this._row; row++){
                let id = this.GetResutByRowCol(cards,row,col);

                if(id === 2){
                    hasScatterList[row] = 1;
                    count += 1;
                }
            }

            // 3个 从上往下依次201 202 203
            let startIdx = hasScatterList.indexOf(1);
            for (let i = 0; i < count; i++){
                let idx = this.ChangeRowColToIdx(cards,i+startIdx,col);
                let subNum = 0
                if(hasScatterList[0]){  // 小于3个且在下面,起始id不为203
                    subNum = (3-count);
                }
                cards[idx] = 203 - i - subNum;
            }

            this._reels[col].setScatterNum(count);
        }

        // console.log(cards);
        return cards
    },

    SetReelStateInfo:function(cards){
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let fireGame = cc.vv.gameData.GetFireGame();
        if(fireGame && fireGame.tri) {   // 触发bonus游戏
            return;
        }

        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % this._col
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0
            let isContinuous = true
            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0 && isContinuous) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = this._reels[i].getScatterNum() > 0 ? 1 : 0;
                haveCount +=  reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount && isContinuous) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                }
                if (stateInfo.continuous && stateInfo.counts[i] > 0 && reelCountOfID == 0) {
                    isContinuous = false
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    StartMove(){
        if(cc.vv.gameData.IsBonusGame()){
            cc.vv.gameData.GetBonusScript().StartMove()   
        } else {
            this._super();
            Global.SlotsSoundMgr.playNormalBgm()
        }
    },

    StopMove(){
        if(cc.vv.gameData.IsBonusGame()){
            // cc.vv.gameData.GetBonusScript().StopMove()
        } else {
            this._super();
        }
    },

    //单列回弹动作之后
    async OnReelBounsActionEnd(colIdx){
        if(colIdx === 0){
            let fireGame = cc.vv.gameData.GetFireGame();
            if(fireGame && fireGame.tri){   // 触发bonus游戏

                let hasCount = 0;
                let hasHsList = [0,0,0,0,0,0];
                let addSym = [];
                let curId = cc.vv.gameData.GetBonusCardId();
                for(let row = 0; row < this._row; row++){
                    let sym = this._reels[colIdx].GetSymbolByRow(row);
                    if(sym.GetShowId() === curId){
                        ++hasCount;
                        hasHsList[row] = 1
                    }else {
                        addSym.push(curId)
                    }
                }
                if(hasCount < 6){
                    this._reels[colIdx].AppendSymbol(addSym, hasHsList[0]?1:2);

                    let mult = hasHsList[0]?1:-1;
                    let s_row = hasHsList[0] ? 6 : hasHsList.lastIndexOf(0);

                    let nudge = cc.find("reels/reel1/spine_nudge", this.node);
                    nudge.position = nudge.parent.convertToNodeSpaceAR(this._reels[colIdx].GetSymbolByRow(s_row).node.convertToWorldSpaceAR(cc.v2(0,0)))
                    nudge.active = true;
                    nudge.setScale(cc.v2(1, hasHsList[0]?-1:1));
                    nudge.getComponent(sp.Skeleton).setAnimation(0,"animation",false);

                    await this.awaitTime(0.5);
                    this._reels[colIdx].reelMove(mult,addSym.length,addSym.length*0.6);

                    let height = this._cfg.symbolSize.height
                    cc.tween(nudge)
                        .to(addSym.length*0.6, {position:cc.v2(nudge.x, mult*addSym.length*height + nudge.y)})
                        .start()

                    await this.awaitTime(addSym.length*0.6);
                    this._reels[colIdx].DelAppendSymbol();
                    nudge.active = false;
                }

                let fire = cc.vv.gameData.GetBonusScript().getMultiFireNode(colIdx,0,6);
                if(fire){
                }else {
                    fire = cc.vv.gameData.GetBonusScript().setMultiFireNode(curId,colIdx,0,6);
                }
                fire.active = true;
                fire.getComponent(sp.Skeleton).setAnimation(0,"animation6_1",false);
                fire.getComponent(sp.Skeleton).addAnimation(0,"animation6",true);

                cc.vv.gameData.GetBonusScript().setPosType(1);

                await this.awaitTime(1);
                cc.vv.gameData.GetPopupScript().playBonusQpAnim();
                await this.awaitTime(0.5);

                for (let i = 1; i < this._col; i++){
                    this._reels[i].StopMove(0);
                }

                await this.awaitTime(0.1);
                cc.vv.gameData.GetBonusScript().triBonusGame();
            }
        }
    },

    //列回弹动作最低点
    OnReelBounsActionDeep(colIdx){
        if(colIdx === this._col-1){
            cc.vv.gameData.setSymbolDark(false);
            this.setBgMask(false);
            this.setAllSymbolMask(false);
        }
    },

    OnSpinEnd(){
        this.onSpinEndAction();
    },

    async onSpinEndAction(){
        let fireGame = this._gameInfo.fireGame //cc.vv.gameData.GetFireGame();
        if(fireGame && fireGame.tri) {   // 触发bonus游戏
            return
        }

        // scatte图标移动
        await this.playScatterNudge();

        // 显示中奖路线
        this.ShowWinTrace()
        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise((sucess, failed)=>{
            this.ShowBottomWin(nWin,nTotal,true,sucess)
        });

        // 触发免费
        let freeInfo = this._gameInfo.freeResult.freeInfo;
        if (freeInfo && freeInfo.freeCnt > 0){
            await this.CheckEnterFreeGame();
        }

        // 免费结束
        if(this._gameInfo.allFreeCnt > 0 && this._gameInfo.freeCnt == 0){
            Global.SlotsSoundMgr.stopBgm();
            await this.CheckExitFreeGame();
            Global.SlotsSoundMgr.playNormalBgm()
        }

        this.CanDoNextRound();
    },

    // scatte图标移动
    playScatterNudge(){
        return new Promise(async (sucess, failed)=> {
            let needMoveCol = [];
            for(let col = 0; col < this._col; col++){
                let count = this._reels[col].getScatterNum();
                if(count > 0 && count < 3){
                    needMoveCol.push(col);
                }
            }

            // 有列要播扩展动画
            if(needMoveCol.length > 0){
                await this.awaitTime(0.2);

                for(let i = 0; i < needMoveCol.length; i++){
                    let col = needMoveCol[i];
                    let count = this._reels[col].getScatterNum();

                    let id_0 = this._reels[col].GetSymbolByRow(0).GetShowId();
                    let isBottom = (id_0 === 201 || id_0 === 202);
                    // console.log(isBottom);

                    let list = [];
                    for (let i = 0; i < 3 - count; i++){
                        if(isBottom){
                            list.unshift(203 - i);
                        }else {
                            list.unshift(201 + i)
                        }
                    }

                    this._reels[col].AppendSymbol(list,isBottom? 1:2);
                    this._reels[col].reelMove(isBottom?1:-1, list.length, 0.3);

                    // 播放动画和音效
                    Global.SlotsSoundMgr.playEffect("nudge_scatter");

                    let allSym = this._reels[col].getAllSymbol()
                    for(let row = 0; row < allSym.length; row++){
                        allSym[row].playNudgeAnim();
                    }
                }

                await this.awaitTime(0.3);
                for (let i = 0; i < needMoveCol.length; i++){
                    this._reels[needMoveCol[i]].DelAppendSymbol();
                }
                await this.awaitTime(0.2);
            }
            sucess();
        });
    },


    // 检查触发免费
    async CheckEnterFreeGame(){
        return new Promise(async (sucess, failed)=>{

            Global.SlotsSoundMgr.playEffect("fg_ling");
            let freeInfo = this._gameInfo.freeResult.freeInfo;
            this._triFreeIdxs = freeInfo.idxs;
            for (let id of this._triFreeIdxs) {
                let symbol = this.GetSymbolByIdx(id);
                if(symbol){
                    symbol.playTriggerAnimation(false)
                }
            }
            await this.awaitTime(1.5);
            this.Backup();

            // 播放免费次数
            await this.showTriFreeAni();

            await cc.vv.gameData.GetPopupScript().showGainFree(freeInfo.freeCnt);
            cc.vv.gameData.GetPopupScript().playFreeQpAnim();

            await this.awaitTime(1.2);

            Global.SlotsSoundMgr.playEffect("frame1");
            this._node_free_spins.active = false;
            this.hideAllFreeCnt();
            this.ShowGameview(true);
            this.playCharacterAnim(true);

            await this.awaitTime(1);
            sucess();
        });
    },

    // 触发免费动画
    async showTriFreeAni(){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("beforefg");

            let lbl_count = cc.find("node_count/lbl_count", this._node_free_spins);
            let spr_count_1 = cc.find("node_count/spine_count_1", this._node_free_spins);
            let spr_count_2 = cc.find("node_count/spine_count_2", this._node_free_spins);
            lbl_count.getComponent(cc.Label).string = "";
            spr_count_1.getComponent(sp.Skeleton).setAnimation(0, "animation1", true);
            spr_count_2.active = false;

            Global.SlotsSoundMgr.playEffect("frame1");
            this._node_free_spins.active = true;
            this._node_free_spins.y = -200;
            cc.tween(this._node_free_spins)
                .to(1, {position: cc.v2(this._node_free_spins.x, 24)})
                .start();

            await this.awaitTime(1);

            let freeInfo = this._gameInfo.freeResult.freeInfo;
            let freeCnt = freeInfo.freeCnt;
            let freeIdxs = freeInfo.idxs;
            let splitList = this.splitCount(freeCnt, freeIdxs.length);

            let countIdx = 0;   // 当前第播放第几个数
            let lbl_cnt = 0;    // 当前显示的总个数

            for (let col = 0; col < this._col && countIdx < splitList.length; col++) {
                for (let row = this._row - 1; row >= 0 && countIdx < splitList.length; row--) {
                    // let sym = this._reels[col].GetSymbolByRow(row);

                    let idx = this.ChangeRowColToIdx(this._gameInfo.resultCards, row, col);
                    if (freeIdxs.includes(idx+1)) {
                        if (countIdx % 2 === 0) {
                            Global.SlotsSoundMgr.playEffect("digital1");
                        } else {
                            Global.SlotsSoundMgr.playEffect("digital2");
                        }

                        let curCnt = splitList[countIdx];
                        this.playFreeCnt(idx+1, curCnt);

                        lbl_cnt += curCnt;
                        lbl_count.active = true;
                        lbl_count.getComponent(cc.Label).string = lbl_cnt;
                        spr_count_2.active = true;
                        spr_count_2.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
                        // spr_count_1.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);

                        countIdx += 1;
                        await this.awaitTime(0.7);
                    }
                }
            }

            sucess();
        });
    },

    // 播放免费次数
    playFreeCnt(idx, cnt){
        this._top_free.active = true;

        let fgNode = cc.find("fg_"+idx, this._top_free);
        fgNode.active = true;
        fgNode.getComponent(sp.Skeleton).setAnimation(0,"animation"+cnt,false);
    },

    // 隐藏所有免费节点
    hideAllFreeCnt(){
        for(let i = 0; i < this._top_free.childrenCount; i++){
            this._top_free.children[i].active = false;
        }
        this._top_free.active = false;
    },

    // 免费结束
    async CheckExitFreeGame() {
        return new Promise(async (sucess, failed) => {
            await cc.vv.gameData.GetPopupScript().showEndFree(cc.vv.gameData.GetGameTotalFreeWin());
            cc.vv.gameData.GetPopupScript().playFreeQpAnim();
            await this.awaitTime(1.2);

            this.Resume();
            // 退出免费恢复卡牌的时候,触发动画需要循环播放
            if(this._triFreeIdxs && this._triFreeIdxs.length > 0){
                for (let id of this._triFreeIdxs) {
                    let symbol = this.GetSymbolByIdx(id);
                    if(symbol){
                        symbol.playTriggerAnimation(true)
                    }
                }
                this._triFreeIdxs = [];
            }
            this.ShowGameview(false);
            this.playCharacterAnim(false);

            await this.awaitTime(1);
            let nWin = cc.vv.gameData.GetGameTotalFreeWin();
            let nTotal = nWin;
            await new Promise((sucess, failed)=>{
                this.ShowBottomWin(nWin,nTotal,true,sucess)
            });
            sucess();
        })
    },

    // 退出小游戏
    async exitBonusGame(){
        Global.SlotsSoundMgr.stopBgm();
        if(cc.vv.gameData.GetTotalFree() > 0 ){
            Global.SlotsSoundMgr.playBgm("free_bgm");

            if(cc.vv.gameData.GetFreeTime() == 0){
                await this.CheckExitFreeGame();
            }
        } else {
            Global.SlotsSoundMgr.playNormalBgm();
        }

        cc.vv.gameData.SetBonusCardId(this._isSixTri ? 111 : 112);

        this.CanDoNextRound()
    },

    //拆分免费获得次数
    splitCount:function(count,des){
        let nums = [1,2,3,5,10];
        let resultNum = [];

        des = des?des:9;
        for( ;des > 0;){
            if (des === 1){
                resultNum.push(count);
                --des;
            }
            else if(des <= 3){   // 最后几次
                let n1 = parseInt(count/2) === 0 ? 1 : parseInt(count/2);
                for(let i = 0; i<nums.length; i++){
                    if(n1 <= nums[i] && n1 > nums[i-1]){
                        if (n1 + des > count){
                            n1 = nums[i-1]
                        }else {
                            n1 = nums[i]
                        }
                    }
                }

                resultNum.push(n1);
                --des;
                count = count-n1;
            }
            else {
                let max = count-des+1;
                let random = parseInt(Math.random()*(max+1)); //获取随机数[0,max]
                random = (random===0)?1:random;
                if(nums.includes(random)){
                    resultNum.push(random);
                    --des;
                    count = count-random;
                }
            }
        }
        resultNum.reverse();
        // console.log(resultNum);
        return resultNum;
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        if(bFree){
            Global.SlotsSoundMgr.playBgm('free_bgm')

            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            //显示免费次数
            this._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetFreeWinCoin()
            this._bottomScript.SetWin(nTotal)

        }
        else{
            this._bottomScript.ShowFreeModel(false)
        }
        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal");
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free");
        if(normalFree){ //存在免费游戏背景才执行下面的逻辑
            if(normalBg){
                normalBg.active = !bFree
            }
            normalFree.active = bFree
        }

        // this.playCharacterAnim(bFree);
        this.showShandianSpineActive(bFree);
    },

    showShandianSpineActive(bShow){
        cc.find("Canvas/safe_node/shandian").active = bShow;
    },

    // 背景mask设置
    setBgMask(bShow){
        let node = cc.find("reels_bg/items_bg/mask", this.node);
        node.active = bShow;
    },

    setAllSymbolMask(bShow){
        for(let col = 0; col < this._reels.length; col++){
            let allSym = this._reels[col].getAllSymbol()
            for(let row = 0; row < allSym.length; row++){
                allSym[row].setMaskVisible(bShow);
            }
        }
    },

    setBannerState(isSix){
        let tit_6 = cc.find("bg_title/title_6",this._node_banner);
        let tit_4 = cc.find("bg_title/title_4",this._node_banner);
        let icon_6 = cc.find("icon_6",this._node_banner);
        let icon_4 = cc.find("icon_4",this._node_banner);
        let spr_6 = cc.find("spr_6",this._node_banner);

        tit_6.active = isSix;
        tit_4.active = !isSix;
        icon_6.active = isSix;
        icon_4.active = !isSix;
        spr_6.active = isSix;
    },

    initBannerState(){
        let curBet = cc.vv.gameData.GetBetIdx();
        let minBet = cc.vv.gameData.GetChangeNumBet();
        if(curBet <= minBet){
            this._isSixTri = true;
            this.setBannerState(true);
        }else {
            this._isSixTri = false;
            this.setBannerState(false);
        }
        cc.vv.gameData.SetBonusCardId(this._isSixTri ? 111 : 112);
    },

    // 押注额改变
    onEventTotalbetUpdated(){
        let spine_change = cc.find("spine_change",this._node_banner);
        spine_change.active = false;

        let curBet = cc.vv.gameData.GetBetIdx();
        let minBet = cc.vv.gameData.GetChangeNumBet();

        if(!this._isSixTri && curBet <= minBet){
            Global.SlotsSoundMgr.playEffect("change1");
            this._isSixTri = true;
            spine_change.active = true;
            spine_change.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);

            this.setBannerState(true);
        }else if (this._isSixTri && curBet > minBet){
            Global.SlotsSoundMgr.playEffect("change1");
            this._isSixTri = false;
            spine_change.active = true;
            spine_change.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);
            this.setBannerState(false);
        }

        cc.vv.gameData.SetBonusCardId(this._isSixTri ? 111 : 112);
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },


    // 播放人物动画
    playCharacterAnim(isSpe){
        let node = cc.find("Canvas/safe_node/leishen");
        if(isSpe) {
            node.stopAllActions();
            node.runAction(cc.repeatForever(cc.sequence(cc.callFunc(()=>{
                node.getComponent(sp.Skeleton).setAnimation(0,"idle",false);
                node.getComponent(sp.Skeleton).addAnimation(0,"idle",false);
                node.getComponent(sp.Skeleton).addAnimation(0,"skill",false)
            }),cc.delayTime(11.2))));
        } else {
            node.stopAllActions();
            node.getComponent(sp.Skeleton).setAnimation(0,"idle",true);
        }

    },


});
