/**
 * 符号表
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _type:"normal",

    },

    Init(idx,node){
        this._super(idx,node)
    },


    setSymType(type){
        this._type = type;
    },

    playBonusShowAnim(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].show_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].show_ani.name != ""){
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].show_ani.name,true)
                }
            }
        }
    },

    playBonusAnimation(animName, bLoop){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node){

            if(animName != ""){
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,animName, bLoop)
                }
            }
        }
    },

    // 节点上升时爆炸动画
    playBoombAnim(){
        let spine = cc.find("bonus_bao",this.node);
        if (spine){
            spine.active = true;
            spine.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
            spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spine.active = false;
            })
        }
    },
    // 节点上升时爆炸动画
    playBonusKuangAnim(){
        let spine = cc.find("fire_kuang",this.node);
        if (spine){
            spine.active = true;
            spine.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
            spine.getComponent(sp.Skeleton).setCompleteListener(()=>{
                spine.active = false;
            })
        }
    },

    // 显示背景（针对12）
    showBg(bShow){
        let bg = cc.find("bg", this.node);
        if(bg){
            bg.active = bShow;
        }
    },

    // 转盘显示结果：奖池和倍率
    ShowWheelResult(mult, jp){
        if(this._showNode){
            this._showNode.active = false
        }
        this._showNode = cc.find("s121_0",this.node);
        this._showNode.active = true;

        let spr_mult = cc.find("spr_mult", this.node);
        let spr_jp = cc.find("spr_jp", this.node);

        spr_mult.active = true;
        spr_jp.active = true;
        spr_mult.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("base_game").getSpriteFrame('theme_wheel_num'+mult);
        spr_jp.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("base_game").getSpriteFrame('theme_jackpot_'+jp);

    },

    ShowRandomSymbol(){
        if(this._type === "bonus"){
            let randomList = cc.vv.gameData.GetBonusRandomList();
            let cfg = cc.vv.gameData.getGameCfg()
            let randIdx = Global.random(1,randomList.length)
            let randVal = randomList[randIdx-1]
            this.ShowById(randVal)
        }else {

            let bonusId = cc.vv.gameData.GetBonusCardId();

            let cfg = cc.vv.gameData.getGameCfg();
            let list = Global.copy(cfg.randomSymbols);
            list.push(bonusId);
            let randIdx = Global.random(1,list.length)
            let randVal = list[randIdx-1]
            this.ShowById(randVal)

            // this._super();
        }

    },

    //赢钱动画
    playWinAnimation(){
        if(this._showNode){
            this._showNode.active = false
        }
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        this._state = "win";
        if(cfg.symbol[id] && cfg.symbol[id].win_node){
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].win_ani && cfg.symbol[id].win_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].win_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].win_ani.name,true)
                }
            }

            this._playNode = topShowNode;
        }
        else{
            //如果没有中奖动画，先显示出来
            //TODO：后续补充一个没有spin动画的显示效果
            this._showNode.active = true
            this._playNode = this._showNode;
        }
        this.playWinTweenAction()
    },

    playWinTweenAction(){
        this._playNode.cleanup()
        //记录原始缩放
        let nScale = this._playNode.scale
        this._showNodeOrgScale = nScale

        cc.tween(this._playNode)
            .repeatForever(cc.tween()
                .to(0.5,{scale:nScale+0.2})
                .to(0.5,{scale:nScale})
                .delay(1)
            )
            .start()
    },

    //停止tween类型的action动画
    stopWinTweenAction(){
        if(this._playNode){
            this._playNode.cleanup()
            this._playNode = null;
        }
    },

    ShowById:function(id,data){
        this._super(id, data);

        this.setMaskVisible(true);
    },

    // 图标置灰
    setMaskVisible(isMask) {
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node && cfg.symbol[this._id].isMask){
            let showNode = cc.find(cfg.symbol[this._id].node,this.node)
            if (isMask && cc.vv.gameData.getSymbolDark()) {
                showNode.color = new cc.Color(105, 105, 105);
            }
            else {
                showNode.color = cc.Color.WHITE;
            }
        }
    },


    playNudgeAnim(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].nudge_ani){
            // this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].nudge_ani.name != ""){
                this.node.zIndex = cfg.symbol[id].nudge_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].nudge_ani.name,false)
                }
            }
        }
    },

    //触发动画
    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(bLoop){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    bLoop = bLoop ? bLoop : false;
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,bLoop)
                }
            }
        }
        return isPlay
    },

    //停止动画
    playStopAnimation(){
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            this._state = "stop";
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].stop_ani.name != ""){
                if(this._type == "normal"){
                    this.node.zIndex = cfg.symbol[id].stop_ani.zIndex - this._symbolIdx  + this._reelIdx*10;
                }
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false)
                }
            }
        }
    },

    Resume(backup) {
        this.stopWinTweenAction();

        this._super(backup);
    },
})
