cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    init(deskInfo,gameId,gameJackpot){

        this._fireGame =  deskInfo.fireGame;
        if(this._fireGame){
            this._bonusRest = this._fireGame.rest;
            this._bonusAll = this._fireGame.all;
            this._bonusTotalWinCoin = this._fireGame.totalWinCoin;

            if(this._fireGame.fire){
                this.setBonusIdByFire(this._fireGame.fire);
            }

            if(this._fireGame.poolList){
                this._poolList = this._fireGame.poolList;
            }
        }

        this._freeWinCoin =  deskInfo.freeWinCoin

        this._super(deskInfo,gameId,gameJackpot);
    },

    OnRcvNetSpine:function(msg){

        if(msg.code == 200) {

            this._fireGame = msg.fireGame;
            if(this._fireGame){
                if(this._fireGame.spineCnt){
                    this._bonusRest = this._fireGame.spineCnt.rest;
                    this._bonusAll = this._fireGame.spineCnt.all;
                    this._bonusTotalWinCoin = this._fireGame.spineCnt.totalWinCoin;
                }
                if(this._fireGame.poolList){
                    this._poolList = this._fireGame.poolList;
                }
            }

            this._freeWinCoin = msg.freeWinCoin
        }


        this._super(msg);
    },

    SetPopupScript(scp){
        this._popupScp = scp;
    },

    GetPopupScript(){
        return this._popupScp;
    },

    SetBonusScript(scp){
        this._bonusScp = scp;
    },

    GetBonusScript(){
        return this._bonusScp;
    },

    SetWheelScript(scp){
        this._wheelScp = scp;
    },

    GetWheelScript(){
        return this._wheelScp;
    },

    // 获取bonus游戏数据
    GetFireGame(){
        return this._fireGame;
    },

    // 四六押注切换
    GetChangeNumBet(){
        return this._fireGame.minBet
    },

    SetIsBonusGame(isBonus){
        this._isBonusGame = isBonus;
    },

    IsBonusGame(){
        return this._isBonusGame;
    },

    // bonus总次数
    GetBonusAll(){
        return this._bonusAll;
    },

    // bonus剩余次数
    GetBonusRest(){
        return this._bonusRest;
    },

    // bonus总赢钱
    GetBonusTotalWinCoin(){
        return this._bonusTotalWinCoin;
    },

    // bonus火神类型 1：蓝色，2：黄色   3：橙色，4：紫色
    setBonusIdByFire(type){
        if(type === 1){
            this.SetBonusCardId(111);
        } else if(type === 2){
            this.SetBonusCardId(112);
        } else if(type === 3){
            this.SetBonusCardId(113);
        } else if(type === 4){
            this.SetBonusCardId(114);
        }
    },

    // bonus游戏当前id类型
    SetBonusCardId(id){
        this._bonusCardId = id;
    },

    GetBonusCardId(){
        return this._bonusCardId;
    },

    // bonus游戏随机图标列表
    SetBonusRandomList(id){
        let list = [12,13,13,13,13];
        list.push(id);
        list.push(id);
        list.push(id);
        list.push(id);
        this._bonusRandomList = list;
    },

    GetBonusRandomList(){
        return this._bonusRandomList;
    },

    // bonus上一局信息 不存在则默认为刚触发那一局
    GetBonusCards(){
        return this._fireGame.cards
    },

    // bonus特殊图标位置以及类型集合 {{idx = 8, rtype = 1},{ idx = 9, rtype = 1}}
    GetBonusSpInfo(){
        return this._fireGame.spInfo
    },

    // bonus当前类型 [1,2,3] 和 [2,3,4]
    GetBonusFireList(){
        return this._fireGame.fireList
    },

    // bonus特殊图标结果 type://1-转盘， 2-提高图标等级  3-增加一排图标  4-将周围格子变成有效图标
    GetBonusSpResult(){
        // this._fireGame.sp_result = {"type":1,"rs":{"rs_1":{"idx":5,"coin":82900},"rs_2":{"idx":7,"coin":82900}}}
        // this._fireGame.sp_result = {"type":2,"rs":{"fire":3},}
        // console.log(this._fireGame)
        return this._fireGame.sp_result
    },

    // 奖池数据
    GetBonusPoolList(){
        return this._poolList;
    },

    GetFreeWinCoin(){
        return this._freeWinCoin;
    },

    // 图标颜色变黑
    setSymbolDark(bDark){
        this._symDark = bDark;
    },

    getSymbolDark(){
        return this._symDark;
    },

    // update (dt) {},
});
