
cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    //初始化公共组件
    InitCommComponent:function() {
        this._super();

        let script_popup = this.node.addComponent("LordOfThunder_Popup")
        script_popup.Init()
        cc.vv.gameData.SetPopupScript(script_popup);

        let script_bonus = this.node.addComponent("LordOfThunder_BonusGame")
        script_bonus.Init()
        cc.vv.gameData.SetBonusScript(script_bonus);

        let script_wheel = this.node.addComponent("LordOfThunder_Wheel")
        script_wheel.Init()
        cc.vv.gameData.SetWheelScript(script_wheel);
    }

});