cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    reelMove(mult, num, time){

        // let mult = isUp?1:-1;
        let height = this._cfg.symbolSize.height
        cc.tween(this._holderNode)
            .to(time,{position:cc.v2(this._holderNode.x,this._holderNode.y+mult*num*height)})
            .start();

    },


    //显示免费游戏加速效果
    //加速框的显示
    ShowAntiEffect:function(bShow,name){
        if (bShow == false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    let node = cc.find(info.antiNode + "_"+(this._reelIdx+1) ,this.node.parent)
                    if(node && node.active){
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if(this._stopRightNow){
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }

                    }
                }
            }
        }else{
            let node = cc.find(name + "_"+(this._reelIdx+1) ,this.node.parent)
            if(node){
                node.active = bShow
                node.getComponent(sp.Skeleton).setAnimation(0,"animation",false)

                cc.vv.gameData.setSymbolDark(true);
                cc.vv.gameData.GetSlotsScript().setBgMask(true);
                cc.vv.gameData.GetSlotsScript().setAllSymbolMask(true);
            }
            else{
                console.log("未找到加速节点：mask/node_anti");
            }
        }
    },

    getAllSymbol(){
        return this._symbols;
    },

    // 一列有的锤子图标个数
    setScatterNum(num){
        this._scatterNum = num;
    },
    getScatterNum(){
        return this._scatterNum;
    },

    // update (dt) {},
});
